// Panels: procedural 9-slice. The nine pieces (four corners, four edges, centre) are generated by
// functions from a few colours, cached, and tiled; the centre is "glass", an index table that
// turns whatever is behind into dark tones of the space ramp, so no alpha is needed.

import { IndexedBuffer, TRANSPARENT } from '../../core/buffer';
import { masterPalette, type IndexTable } from '../../toolkit/palette';
import { blit, tint } from '../draw';

const palette = masterPalette();

export interface PanelStyle {
  readonly border: number;
  /** Bevel: lit top and left, shaded bottom and right. */
  readonly light: number;
  readonly shade: number;
  /** A pixel of colour in each corner. */
  readonly accent: number;
  readonly glass: IndexTable;
}

/** Everything behind a panel becomes dark navy, keeping a faint silhouette of its lightness. */
function glassTable(): IndexTable {
  const table = palette.identityTable();
  const space = palette.ramp('space').indices;
  for (let i = 1; i < palette.size; i++) {
    const l = palette.lightnessOf(i);
    table[i] = space[l > 0.55 ? 2 : l > 0.3 ? 1 : 0];
  }
  return table;
}

export const GLASS = glassTable();

export const PANEL: PanelStyle = {
  border: palette.index('ui-cool', 1),
  light: palette.index('ui-cool', 2),
  shade: palette.index('space', 1),
  accent: palette.index('ui-warm', 2),
  glass: GLASS,
};

export const PANEL_WARM: PanelStyle = {
  border: palette.index('ui-warm', 1),
  light: palette.index('ui-warm', 2),
  shade: palette.index('space', 1),
  accent: palette.index('ui-cool', 2),
  glass: GLASS,
};

const K = 4;

/**
 * One corner piece, K x K, for the top-left corner; the others are its mirror images with the
 * bevel colours swapped where the light does not reach.
 */
function corner(style: PanelStyle, right: boolean, bottom: boolean): IndexedBuffer {
  const b = new IndexedBuffer(K, K);
  for (let y = 0; y < K; y++) {
    for (let x = 0; x < K; x++) {
      // Local coordinates measured from the outer corner.
      const u = right ? K - 1 - x : x;
      const v = bottom ? K - 1 - y : y;
      if (u + v < 2) continue; // rounded: the outermost pixels stay transparent
      if (u === 0 || v === 0 || u + v === 2) b.set(x, y, style.border);
      else if (u === 1 || v === 1) {
        // The inner line belongs to a horizontal edge (v = 1) or a vertical one (u = 1).
        const lit = u === 1 && v === 1 ? !bottom && !right : v === 1 ? !bottom : !right;
        b.set(x, y, lit ? style.light : style.shade);
      }
      else if (u === 2 && v === 2) b.set(x, y, style.accent);
    }
  }
  return b;
}

/** Edge piece: one column (top, bottom) or one row (left, right), repeated along the edge. */
function edge(style: PanelStyle, side: 'top' | 'bottom' | 'left' | 'right'): IndexedBuffer {
  const vertical = side === 'left' || side === 'right';
  const b = new IndexedBuffer(vertical ? K : 1, vertical ? 1 : K);
  const inner = side === 'top' || side === 'left' ? style.light : style.shade;
  for (let t = 0; t < K; t++) {
    const u = side === 'right' || side === 'bottom' ? K - 1 - t : t;
    const colour = u === 0 ? style.border : u === 1 ? inner : TRANSPARENT;
    if (vertical) b.set(t, 0, colour);
    else b.set(0, t, colour);
  }
  return b;
}

interface Pieces {
  tl: IndexedBuffer;
  tr: IndexedBuffer;
  bl: IndexedBuffer;
  br: IndexedBuffer;
  top: IndexedBuffer;
  bottom: IndexedBuffer;
  left: IndexedBuffer;
  right: IndexedBuffer;
}

const cache = new Map<PanelStyle, Pieces>();

function pieces(style: PanelStyle): Pieces {
  let p = cache.get(style);
  if (p === undefined) {
    p = {
      tl: corner(style, false, false),
      tr: corner(style, true, false),
      bl: corner(style, false, true),
      br: corner(style, true, true),
      top: edge(style, 'top'),
      bottom: edge(style, 'bottom'),
      left: edge(style, 'left'),
      right: edge(style, 'right'),
    };
    cache.set(style, p);
  }
  return p;
}

/** Draws a panel: glass centre, bevelled edges, rounded corners. */
export function panel(fb: IndexedBuffer, x: number, y: number, w: number, h: number, style: PanelStyle = PANEL): void {
  const p = pieces(style);
  // Centre: glass over the whole inside (corners are drawn on top).
  tint(fb, x + 1, y + 1, w - 2, h - 2, style.glass);
  for (let i = x + K; i < x + w - K; i++) {
    blit(fb, p.top, i, y);
    blit(fb, p.bottom, i, y + h - K);
  }
  for (let j = y + K; j < y + h - K; j++) {
    blit(fb, p.left, x, j);
    blit(fb, p.right, x + w - K, j);
  }
  blit(fb, p.tl, x, y);
  blit(fb, p.tr, x + w - K, y);
  blit(fb, p.bl, x, y + h - K);
  blit(fb, p.br, x + w - K, y + h - K);
}
